#include <stdio.h>

int main(void) {
    for (int i = 11; i < 100; i++) {
        int resto = i % 10;
        int quoc = i / 10;
        if (resto != 0 && i % quoc == 0) {
            printf("%d\n", i);
        }
    }
    return 0;
}

#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    for (int l = 1; l < n; l++) {
        for (int c = l + 1; c <= n; c++) {
            printf("%d-%d%s", l, c, c == n ? "" : " ");
        }
        printf("\n");
    }
    return 0;
}

#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    for (int l = 2; l <= n; l++) {
        for (int c = n + 2 - l; c <= n; c++) {
            printf("%d-%d%s", l, c, c == n ? "" : " ");
        }
        printf("\n");
    }
    return 0;
}

#include <stdio.h>
#include <math.h>

int main(void) {
    double a, b, c;
    scanf("%lf %lf %lf", &a, &b, &c);
    if (a == 0.0) {
        printf("Nao e equacao do 2 grau\n");
    } else {
        double d = b * b - 4.0 * a * c;
        if (d >= 0.0) {
            double x1 = (-b + sqrt(d)) / (2.0 * a);
            double x2 = (-b - sqrt(d)) / (2.0 * a);
            printf("%.4f\n%.4f\n", x1, x2);
        } else {
            printf("Nao ha raizes reais\n");
        }
    }
    return 0;
}

#include <stdio.h>

int main(void) {
    int n1, n2, n3, n4, n5;
    scanf("%d %d %d %d %d", &n1, &n2, &n3, &n4, &n5);
    if (n1!=n2 && n1!=n3 && n1!=n4 && n1!=n5 && n2!=n3 && n2!=n4 && n2!=n5 && n3!=n4 && n3!=n5 && n4!=n5) {
        int maior = n1 > n2 ? n1 : n2;
        int menor = n1 < n2 ? n1 : n2;
        if (n3 > maior) maior = n3; else if (n3 < menor) menor = n3;
        if (n4 > maior) maior = n4; else if (n4 < menor) menor = n4;
        if (n5 > maior) maior = n5; else if (n5 < menor) menor = n5;
        printf("%d\n%d\n", maior, menor);
    } else {
        printf("Os valores devem ser diferentes\n");
    }
    return 0;
}

#include <stdio.h>

int main(void) {
    int p1, p2, p3, aux;
    scanf("%d %d %d", &p1, &p2, &p3);
    if (p1 < p2) { aux = p1; p1 = p2; p2 = aux; }
    if (p1 < p3) { aux = p1; p1 = p3; p3 = aux; }
    if (p2 < p3) { aux = p2; p2 = p3; p3 = aux; }
    printf("%d %d %d\n", p1, p2, p3);
    int soma = p1 + p2 + p3;
    if (soma > 100) printf("%.2f\n", soma / 3.0);
    else printf("Equipe desclassificada\n");
    return 0;
}

#include <stdio.h>

int main(void) {
    double saldo, credito;
    scanf("%lf", &saldo);
    if (saldo <= 500.0) credito = 0.0;
    else if (saldo <= 1000.0) credito = saldo * 0.3;
    else if (saldo <= 3000.0) credito = saldo * 0.4;
    else credito = saldo * 0.5;
    printf("%.2f\n%.2f\n", saldo, credito);
    return 0;
}

